head.script:
scwin.onpageload = function() {
	var json = [
		{
			"ID": "홍길동",
			"ID2": "홍길동"
		},
		{
			"ID": "",
			"ID2": ""
		}
	];
	dataList1.setJSON(json);
};
scwin.trigger1_onclick = function() {
	// setColumnEditFormat(colIndex, format)
	gridView1.setColumnEditFormat(0, "K{KK}K");
}
scwin.trigger1__onclick = function() {
	var result = gridView1.getColumnEditFormat(0);
	console.log("getColumnEditFormat : " + result);
}
scwin.trigger12_onclick = function() {
	gridView1.setColumnEditPlaceholderChar(0, "_");
}
scwin.trigger13_onclick = function() {
	var result = gridView1.getColumnEditPlaceholderChar(0);
	console.log("getColumnEditPlaceholderChar : " + result);
}
scwin.trigger2_onclick = function() {
	dataList1.setCellData(0, 0, "가나다");
}
scwin.trigger3_onclick = function() {
	var result = dataList1.getCellData(0, 0);
	console.log("getCellData : " + result);
}
scwin.trigger4_onclick = function() {
	var result = gridView1.getCellDisplayData(0, 0);
	console.log("getCellDisplayData : " + result);
}

scwin.trigger1_2_onclick = function() {
	// setColumnEditFormat(colIndex, format)
	gridView1.setColumnEditFormat(1, "K{KK}K");
}
scwin.trigger1_2__onclick = function() {
	var result = gridView1.getColumnEditFormat(1);
	console.log("getColumnEditFormat : " + result);
}
scwin.trigger14_onclick = function() {
	gridView1.setColumnEditPlaceholderChar(1, "");
}
scwin.trigger15_onclick = function() {
	var result = gridView1.getColumnEditPlaceholderChar(1);
	console.log("getColumnEditPlaceholderChar : " + result);
}
scwin.trigger2_2_onclick = function() {
	dataList1.setCellData(0, 1, "가나다");
}
