	var result = dataList1.getCellData(0, 1);
	console.log("getCellData : " + result);
}
scwin.trigger4_2_onclick = function() {
	var result = gridView1.getCellDisplayData(0, 1);
	console.log("getCellDisplayData : " + result);
}

scwin.trigger99_onclick = function() {
	var excelOpt = {
		fileName: "excelData.xls",
		type: 1
	};

	gridView1.advancedExcelDownload(excelOpt);
}
